// Single-file build of supabase/functions/ai-gateway for pasting into the
// Supabase dashboard (Edge Functions → Deploy a new function → via editor).
// Generated by scripts/bundle-ai-gateway.mjs — edit the multi-file source,
// not this file.

import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { createClient, type SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2";

// ───── _shared/cors.ts ─────
export const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers":
    "authorization, x-client-info, apikey, content-type, x-supabase-client-platform, x-supabase-client-platform-version, x-supabase-client-runtime, x-supabase-client-runtime-version",
  "Access-Control-Allow-Methods": "POST, OPTIONS",
};

export function json(body: unknown, status = 200, extra: Record<string, string> = {}): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: { ...corsHeaders, "content-type": "application/json", ...extra },
  });
}

// ───── _shared/pricing.ts ─────
/**
 * Pure pricing helpers shared by the ai-gateway edge function and the
 * frontend quote engine. No Deno or browser APIs here so vitest can run it.
 */

export interface TokenUsage {
  input_tokens: number;
  output_tokens: number;
  cache_read_tokens: number;
  cache_write_tokens: number;
}

export interface ModelRate {
  input_per_1m: number;
  output_per_1m: number;
  cache_read_per_1m?: number | null;
  cache_write_per_1m?: number | null;
}

export interface CreditEconomics {
  retail_usd_per_credit: number;
  cogs_multiplier: number;
}

export const DEFAULT_CREDIT_ECONOMICS: CreditEconomics = {
  retail_usd_per_credit: 0.02,
  cogs_multiplier: 5,
};

export const EMPTY_USAGE: TokenUsage = {
  input_tokens: 0,
  output_tokens: 0,
  cache_read_tokens: 0,
  cache_write_tokens: 0,
};

/** Provider cost in USD for one call. Cache tiers fall back to the input rate. */
export function costFromUsage(usage: TokenUsage, rate: ModelRate | null | undefined): number {
  if (!rate) return 0;
  const cacheRead = rate.cache_read_per_1m ?? rate.input_per_1m;
  const cacheWrite = rate.cache_write_per_1m ?? rate.input_per_1m;
  const cost =
    (usage.input_tokens * rate.input_per_1m +
      usage.output_tokens * rate.output_per_1m +
      usage.cache_read_tokens * cacheRead +
      usage.cache_write_tokens * cacheWrite) /
    1_000_000;
  return round(cost, 6);
}

/** What one credit costs the platform, given retail price and markup. */
export function creditCogsUsd(econ: CreditEconomics): number {
  if (!econ.cogs_multiplier || econ.cogs_multiplier <= 0) return econ.retail_usd_per_credit;
  return econ.retail_usd_per_credit / econ.cogs_multiplier;
}

/** Credits a given provider cost is worth. Fractional; callers round. */
export function creditsFromCost(costUsd: number, econ: CreditEconomics): number {
  const perCredit = creditCogsUsd(econ);
  if (perCredit <= 0) return 0;
  return round(costUsd / perCredit, 4);
}

/** Whole credits to charge for a cost. Never undercharges. */
export function billableCredits(costUsd: number, econ: CreditEconomics): number {
  const raw = creditsFromCost(costUsd, econ);
  return raw <= 0 ? 0 : Math.max(1, Math.ceil(raw - 1e-9));
}

/**
 * Normalize the usage block each provider returns into one shape.
 * Anthropic: input_tokens excludes cache tokens.
 * OpenAI-compatible: prompt_tokens includes cached tokens; subtract them.
 * Google: promptTokenCount includes cachedContentTokenCount; subtract.
 */
export function normalizeUsage(providerKind: "anthropic" | "openai" | "google", raw: any): TokenUsage {
  if (!raw) return { ...EMPTY_USAGE };
  const n = (v: unknown) => (typeof v === "number" && isFinite(v) ? v : 0);
  switch (providerKind) {
    case "anthropic":
      return {
        input_tokens: n(raw.input_tokens),
        output_tokens: n(raw.output_tokens),
        cache_read_tokens: n(raw.cache_read_input_tokens),
        cache_write_tokens: n(raw.cache_creation_input_tokens),
      };
    case "openai": {
      const cached = n(raw.prompt_tokens_details?.cached_tokens);
      return {
        input_tokens: Math.max(0, n(raw.prompt_tokens) - cached),
        output_tokens: n(raw.completion_tokens),
        cache_read_tokens: cached,
        cache_write_tokens: 0,
      };
    }
    case "google": {
      const cached = n(raw.cachedContentTokenCount);
      return {
        input_tokens: Math.max(0, n(raw.promptTokenCount) - cached),
        output_tokens: n(raw.candidatesTokenCount) + n(raw.thoughtsTokenCount),
        cache_read_tokens: cached,
        cache_write_tokens: 0,
      };
    }
  }
}

function round(v: number, places: number): number {
  const f = Math.pow(10, places);
  return Math.round(v * f) / f;
}

// ───── _shared/providers.ts ─────
/**
 * Provider adapters for the ai-gateway. Each adapter turns a normalized
 * request into one provider call and returns text + normalized usage.
 * Streaming adapters emit text deltas through `onChunk` and resolve with the
 * full text and usage when the stream ends.
 */

export interface ChatMessage {
  role: "user" | "assistant" | "system";
  content: string | Array<{ type: string; text?: string; image_url?: { url: string } }>;
}

export interface ProviderRequest {
  modelId: string;
  messages: ChatMessage[];
  systemPrompt?: string;
  maxTokens: number;
  temperature?: number;
  imageBase64?: string;
  imageMimeType?: string;
  /** Mark the system prompt and the first user message as cacheable. */
  cacheContext?: boolean;
  stream?: boolean;
  onChunk?: (text: string) => void;
  signal?: AbortSignal;
}

export interface ProviderResponse {
  text: string;
  usage: TokenUsage;
  raw?: unknown;
}

export interface ProviderConfig {
  slug: string;
  base_url: string;
  auth_header_name: string;
  auth_header_prefix: string;
  apiKey: string;
}

export class ProviderError extends Error {
  status: number;
  constructor(message: string, status = 502) {
    super(message);
    this.status = status;
  }
}

export type ProviderKind = "anthropic" | "google" | "openai";

export function providerKind(slug: string): ProviderKind {
  if (slug === "anthropic") return "anthropic";
  if (slug === "google-ai-studio" || slug === "google") return "google";
  return "openai";
}

/** Text of a message regardless of shape. */
function textOf(content: ChatMessage["content"]): string {
  if (typeof content === "string") return content;
  if (Array.isArray(content)) {
    return content
      .filter((b) => b.type === "text" && typeof b.text === "string")
      .map((b) => b.text as string)
      .join("\n");
  }
  return content == null ? "" : JSON.stringify(content);
}

/** Read an SSE stream and call `onEvent` with each parsed `data:` JSON payload. */
async function readSse(
  body: ReadableStream<Uint8Array>,
  onEvent: (data: any) => void,
): Promise<void> {
  const reader = body.getReader();
  const decoder = new TextDecoder();
  let buffer = "";
  while (true) {
    const { value, done } = await reader.read();
    if (done) break;
    buffer += decoder.decode(value, { stream: true });
    let idx: number;
    while ((idx = buffer.indexOf("\n")) >= 0) {
      const line = buffer.slice(0, idx).trimEnd();
      buffer = buffer.slice(idx + 1);
      if (!line.startsWith("data:")) continue;
      const payload = line.slice(5).trim();
      if (!payload || payload === "[DONE]") continue;
      try {
        onEvent(JSON.parse(payload));
      } catch {
        // partial or non-JSON line; ignore
      }
    }
  }
}

// ── Anthropic ────────────────────────────────────────────────────────────────

export async function callAnthropic(cfg: ProviderConfig, req: ProviderRequest): Promise<ProviderResponse> {
  const system = req.systemPrompt
    ? [{ type: "text", text: req.systemPrompt, ...(req.cacheContext ? { cache_control: { type: "ephemeral" } } : {}) }]
    : undefined;

  const messages = req.messages
    .filter((m) => m.role !== "system")
    .map((m, i) => {
      const text = textOf(m.content);
      const blocks: any[] = [{ type: "text", text }];
      if (i === 0 && req.cacheContext && text.length > 500) {
        blocks[0].cache_control = { type: "ephemeral" };
      }
      return { role: m.role, content: blocks };
    });

  if (req.imageBase64 && messages.length) {
    const last = messages[messages.length - 1];
    if (last.role === "user") {
      last.content.unshift({
        type: "image",
        source: { type: "base64", media_type: req.imageMimeType ?? "image/jpeg", data: req.imageBase64 },
      });
    }
  }

  const res = await fetch("https://api.anthropic.com/v1/messages", {
    method: "POST",
    signal: req.signal,
    headers: {
      "content-type": "application/json",
      "x-api-key": cfg.apiKey,
      "anthropic-version": "2023-06-01",
    },
    body: JSON.stringify({
      model: req.modelId,
      max_tokens: req.maxTokens,
      system,
      messages,
      stream: !!req.stream,
      ...(req.temperature != null ? { temperature: req.temperature } : {}),
    }),
  });

  if (!res.ok) {
    const err = await safeJson(res);
    throw new ProviderError(err?.error?.message ?? `Anthropic error ${res.status}`, res.status);
  }

  if (!req.stream) {
    const data = await res.json();
    const text = (data.content ?? []).filter((b: any) => b.type === "text").map((b: any) => b.text).join("");
    return { text, usage: normalizeUsage("anthropic", data.usage), raw: data };
  }

  let text = "";
  let usage: TokenUsage = { ...EMPTY_USAGE };
  await readSse(res.body!, (ev) => {
    if (ev.type === "message_start" && ev.message?.usage) {
      usage = normalizeUsage("anthropic", ev.message.usage);
    } else if (ev.type === "content_block_delta" && ev.delta?.type === "text_delta") {
      text += ev.delta.text;
      req.onChunk?.(ev.delta.text);
    } else if (ev.type === "message_delta" && ev.usage) {
      usage.output_tokens = ev.usage.output_tokens ?? usage.output_tokens;
    } else if (ev.type === "error") {
      throw new ProviderError(ev.error?.message ?? "Anthropic stream error");
    }
  });
  return { text, usage };
}

// ── Google AI Studio ─────────────────────────────────────────────────────────

export async function callGoogle(cfg: ProviderConfig, req: ProviderRequest): Promise<ProviderResponse> {
  // Google needs strict user/model alternation and no empty parts.
  const contents: Array<{ role: "user" | "model"; parts: any[] }> = [];
  for (const m of req.messages) {
    if (m.role === "system") continue;
    const text = textOf(m.content).trim();
    if (!text) continue;
    const role = m.role === "assistant" ? "model" : "user";
    const last = contents[contents.length - 1];
    if (last && last.role === role) {
      last.parts[0].text += "\n" + text;
    } else {
      contents.push({ role, parts: [{ text }] });
    }
  }
  while (contents.length && contents[0].role === "model") contents.shift();
  if (!contents.length) throw new ProviderError("No valid messages to send", 400);

  if (req.imageBase64) {
    const last = contents[contents.length - 1];
    if (last.role === "user") {
      last.parts.unshift({ inlineData: { mimeType: req.imageMimeType ?? "image/jpeg", data: req.imageBase64 } });
    }
  }

  // Accept a bare host or a versioned base from the provider row.
  let base = (cfg.base_url || "https://generativelanguage.googleapis.com/v1beta").replace(/\/$/, "");
  if (!/\/v1(beta)?$/.test(base)) base += "/v1beta";
  const method = req.stream ? "streamGenerateContent?alt=sse" : "generateContent";
  const url = `${base}/models/${encodeURIComponent(req.modelId)}:${method}`;

  const res = await fetch(url, {
    method: "POST",
    signal: req.signal,
    headers: { "content-type": "application/json", "x-goog-api-key": cfg.apiKey },
    body: JSON.stringify({
      contents,
      ...(req.systemPrompt ? { systemInstruction: { parts: [{ text: req.systemPrompt }] } } : {}),
      generationConfig: { maxOutputTokens: req.maxTokens, temperature: req.temperature ?? 0.8 },
    }),
  });

  if (!res.ok) {
    const err = await safeJson(res);
    throw new ProviderError(err?.error?.message ?? `Google AI error ${res.status}`, res.status);
  }

  const extract = (data: any) =>
    (data?.candidates?.[0]?.content?.parts ?? []).map((p: any) => p.text ?? "").join("");

  if (!req.stream) {
    const data = await res.json();
    const text = extract(data);
    if (!text) throw new ProviderError("Google AI returned an empty response");
    return { text, usage: normalizeUsage("google", data.usageMetadata), raw: data };
  }

  let text = "";
  let usageRaw: any = null;
  await readSse(res.body!, (ev) => {
    const piece = extract(ev);
    if (piece) {
      text += piece;
      req.onChunk?.(piece);
    }
    if (ev.usageMetadata) usageRaw = ev.usageMetadata;
  });
  return { text, usage: normalizeUsage("google", usageRaw) };
}

// ── OpenAI-compatible (OpenAI, DeepInfra, Together, hosted gateways, …) ──────

export async function callOpenAICompatible(cfg: ProviderConfig, req: ProviderRequest): Promise<ProviderResponse> {
  const messages: any[] = req.messages.map((m) => ({ role: m.role, content: m.content }));
  if (req.systemPrompt) messages.unshift({ role: "system", content: req.systemPrompt });

  if (req.imageBase64 && messages.length) {
    const last = messages[messages.length - 1];
    if (last.role === "user") {
      last.content = [
        { type: "image_url", image_url: { url: `data:${req.imageMimeType ?? "image/jpeg"};base64,${req.imageBase64}` } },
        { type: "text", text: textOf(last.content) },
      ];
    }
  }

  // Normalize any non-string, non-array content so the API never sees objects.
  for (const m of messages) {
    if (typeof m.content !== "string" && !Array.isArray(m.content)) m.content = JSON.stringify(m.content);
  }

  const headerName = cfg.auth_header_name || "Authorization";
  const headerValue = cfg.auth_header_prefix ? `${cfg.auth_header_prefix} ${cfg.apiKey}` : cfg.apiKey;
  const base = cfg.base_url.replace(/\/$/, "");
  const maxTokensKey = cfg.slug === "openai" ? "max_completion_tokens" : "max_tokens";

  const res = await fetch(`${base}/chat/completions`, {
    method: "POST",
    signal: req.signal,
    headers: { "content-type": "application/json", [headerName]: headerValue },
    body: JSON.stringify({
      model: req.modelId,
      messages,
      [maxTokensKey]: req.maxTokens,
      ...(req.temperature != null ? { temperature: req.temperature } : {}),
      ...(req.stream ? { stream: true, stream_options: { include_usage: true } } : {}),
    }),
  });

  if (!res.ok) {
    const err = await safeJson(res);
    throw new ProviderError(err?.error?.message ?? `${cfg.slug} error ${res.status}`, res.status);
  }

  if (!req.stream) {
    const data = await res.json();
    const text = data.choices?.[0]?.message?.content ?? "";
    return { text, usage: normalizeUsage("openai", data.usage), raw: data };
  }

  let text = "";
  let usageRaw: any = null;
  await readSse(res.body!, (ev) => {
    const piece = ev.choices?.[0]?.delta?.content;
    if (typeof piece === "string" && piece) {
      text += piece;
      req.onChunk?.(piece);
    }
    if (ev.usage) usageRaw = ev.usage;
  });
  return { text, usage: normalizeUsage("openai", usageRaw) };
}

export async function callProvider(cfg: ProviderConfig, req: ProviderRequest): Promise<ProviderResponse> {
  switch (providerKind(cfg.slug)) {
    case "anthropic":
      return callAnthropic(cfg, req);
    case "google":
      return callGoogle(cfg, req);
    default:
      return callOpenAICompatible(cfg, req);
  }
}

async function safeJson(res: Response): Promise<any> {
  try {
    return await res.json();
  } catch {
    return null;
  }
}

// ───── ai-gateway/index.ts ─────
/**
 * ai-gateway — the single server-side path for LLM inference.
 *
 * Why: provider keys used to be read from ai_providers in the browser and
 * sent straight to Google/Anthropic. Now the browser sends a task, the
 * gateway resolves the model, holds the key, calls the provider, records
 * usage + cost in ai_usage_log, and returns text (JSON or SSE).
 *
 * Request (POST, user JWT in Authorization):
 * {
 *   taskType: string,                    // 'mentor_chat', 'template_generation', …
 *   modelTier?: 'fast'|'standard'|'reasoning',  // agents ask by tier, not model
 *   messages: {role, content}[],
 *   systemPrompt?: string,
 *   maxTokens?: number,
 *   temperature?: number,
 *   overrideModelId?: string,
 *   imageBase64?: string, imageMimeType?: string,
 *   stream?: boolean,                    // SSE response when true
 *   generationId?: string,               // attach usage/cost to a generation row
 *   cacheContext?: boolean,              // default true
 *   metadata?: object                    // copied onto the usage log row
 * }
 *
 * JSON response: { success, text, modelUsed, providerUsed, usage, costUsd, creditsEquivalent, usageLogId }
 * SSE events:    {type:'chunk', text} … {type:'done', …same fields as JSON…} | {type:'error', error}
 */

const SUPABASE_URL = Deno.env.get("SUPABASE_URL")!;
const SERVICE_ROLE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
const ANON_KEY = Deno.env.get("SUPABASE_ANON_KEY")!;

const TIERS = new Set(["fast", "standard", "reasoning"]);

interface GatewayRequest {
  taskType: string;
  modelTier?: string;
  messages: ChatMessage[];
  systemPrompt?: string;
  maxTokens?: number;
  temperature?: number;
  overrideModelId?: string;
  imageBase64?: string;
  imageMimeType?: string;
  stream?: boolean;
  generationId?: string;
  cacheContext?: boolean;
  metadata?: Record<string, unknown>;
}

interface ResolvedModel {
  modelId: string;
  modelName: string;
  provider: { id: string; slug: string; base_url: string; auth_header_name: string; auth_header_prefix: string; is_enabled: boolean };
  costPer1kInput: number | null;
  costPer1kOutput: number | null;
}

serve(async (req) => {
  if (req.method === "OPTIONS") return new Response(null, { headers: corsHeaders });
  if (req.method !== "POST") return json({ success: false, error: "POST only" }, 405);

  const admin = createClient(SUPABASE_URL, SERVICE_ROLE_KEY, { auth: { persistSession: false } });

  // ── Auth ──
  const authHeader = req.headers.get("Authorization") ?? "";
  const token = authHeader.replace(/^Bearer\s+/i, "");
  let userId: string | null = null;
  let isServiceCall = false;
  if (token && token === SERVICE_ROLE_KEY) {
    isServiceCall = true;
  } else if (token) {
    const userClient = createClient(SUPABASE_URL, ANON_KEY, {
      global: { headers: { Authorization: `Bearer ${token}` } },
      auth: { persistSession: false },
    });
    const { data } = await userClient.auth.getUser();
    userId = data.user?.id ?? null;
  }
  if (!userId && !isServiceCall) return json({ success: false, error: "Unauthorized" }, 401);

  // ── Parse ──
  let body: GatewayRequest;
  try {
    body = await req.json();
  } catch {
    return json({ success: false, error: "Invalid JSON body" }, 400);
  }
  if (isServiceCall && typeof (body as any).userId === "string") userId = (body as any).userId;
  if (!body.taskType || !Array.isArray(body.messages) || body.messages.length === 0) {
    return json({ success: false, error: "taskType and messages are required" }, 400);
  }
  const tier = body.modelTier && TIERS.has(body.modelTier) ? body.modelTier : null;
  const maxTokens = clamp(body.maxTokens ?? 2000, 16, 65536);

  // ── Resolve model + key ──
  let resolved: ResolvedModel | null;
  try {
    resolved = await resolveModel(admin, body.taskType, tier, userId);
  } catch (e) {
    return json({ success: false, error: (e as Error).message }, 500);
  }
  if (!resolved) {
    const where = tier ? `tier_${tier}` : body.taskType;
    return json({ success: false, error: `No AI model configured for ${where}. Set it in Admin → AI Models → Task Defaults.` }, 422);
  }
  if (!resolved.provider.is_enabled) {
    return json({ success: false, error: `Provider ${resolved.provider.slug} is disabled.` }, 422);
  }
  const modelId = body.overrideModelId || resolved.modelId;
  const apiKey = await providerKey(admin, resolved.provider.id, resolved.provider.slug);
  if (!apiKey) {
    return json({ success: false, error: `No API key configured for provider ${resolved.provider.slug}. Add it in Admin → AI Models → Providers.` }, 422);
  }

  const cfg: ProviderConfig = {
    slug: resolved.provider.slug,
    base_url: baseUrlFor(resolved.provider),
    auth_header_name: resolved.provider.auth_header_name,
    auth_header_prefix: resolved.provider.auth_header_prefix,
    apiKey,
  };

  // Rates + economics are read once per call; both are small tables.
  const [rate, econ] = await Promise.all([
    modelRate(admin, cfg.slug, modelId, resolved),
    creditEconomics(admin),
  ]);

  const started = Date.now();
  const finish = async (text: string, usage: TokenUsage, success: boolean, error?: string) => {
    const costUsd = costFromUsage(usage, rate);
    const credits = creditsFromCost(costUsd, econ);
    const latency = Date.now() - started;
    const { data: logRow } = await admin
      .from("ai_usage_log")
      .insert({
        user_id: userId,
        generation_id: body.generationId ?? null,
        task_type: body.taskType,
        model_tier: tier,
        provider_slug: cfg.slug,
        model_id: modelId,
        input_tokens: usage.input_tokens,
        output_tokens: usage.output_tokens,
        cache_read_tokens: usage.cache_read_tokens,
        cache_write_tokens: usage.cache_write_tokens,
        cost_usd: costUsd,
        credits_equivalent: credits,
        latency_ms: latency,
        success,
        error_message: error ?? null,
        metadata: { ...(body.metadata ?? {}), stream: !!body.stream, max_tokens: maxTokens, rate_found: !!rate },
      })
      .select("id")
      .single();

    if (body.generationId && success) {
      // Keep the generation row's provider cost in step with what we spent.
      await admin.rpc("add_generation_provider_cost", {
        p_generation_id: body.generationId,
        p_cost_usd: costUsd,
        p_provider: cfg.slug,
        p_model: modelId,
        p_usage: usage,
      }).then(({ error: rpcErr }: any) => {
        if (rpcErr) console.warn("[ai-gateway] add_generation_provider_cost:", rpcErr.message);
      });
    }

    return {
      success,
      text,
      error,
      modelUsed: modelId,
      providerUsed: cfg.slug,
      usage,
      costUsd,
      creditsEquivalent: credits,
      latencyMs: latency,
      usageLogId: logRow?.id ?? null,
    };
  };

  const providerReq = {
    modelId,
    messages: body.messages,
    systemPrompt: body.systemPrompt,
    maxTokens,
    temperature: body.temperature,
    imageBase64: body.imageBase64,
    imageMimeType: body.imageMimeType,
    cacheContext: body.cacheContext !== false,
  };

  // ── Non-streaming ──
  if (!body.stream) {
    try {
      const out = await callProvider(cfg, providerReq);
      if (!out.text) {
        const r = await finish("", out.usage, false, "Provider returned an empty response");
        return json(r, 502);
      }
      return json(await finish(out.text, out.usage, true));
    } catch (e) {
      const status = e instanceof ProviderError ? e.status : 500;
      const r = await finish("", zeroUsage(), false, (e as Error).message);
      return json(r, status >= 400 && status < 600 ? status : 502);
    }
  }

  // ── Streaming (SSE) ──
  const encoder = new TextEncoder();
  const stream = new ReadableStream<Uint8Array>({
    async start(controller) {
      const send = (ev: unknown) => controller.enqueue(encoder.encode(`data: ${JSON.stringify(ev)}\n\n`));
      try {
        const out = await callProvider(cfg, {
          ...providerReq,
          stream: true,
          onChunk: (text) => send({ type: "chunk", text }),
        });
        const r = await finish(out.text, out.usage, !!out.text, out.text ? undefined : "Provider returned an empty response");
        send({ type: r.success ? "done" : "error", ...r });
      } catch (e) {
        const r = await finish("", zeroUsage(), false, (e as Error).message);
        send({ type: "error", ...r });
      } finally {
        controller.close();
      }
    },
  });

  return new Response(stream, {
    headers: { ...corsHeaders, "content-type": "text/event-stream", "cache-control": "no-cache", connection: "keep-alive" },
  });
});

// ── helpers ──────────────────────────────────────────────────────────────────

function clamp(n: number, lo: number, hi: number): number {
  return Math.min(hi, Math.max(lo, Math.floor(Number(n) || lo)));
}

function zeroUsage(): TokenUsage {
  return { input_tokens: 0, output_tokens: 0, cache_read_tokens: 0, cache_write_tokens: 0 };
}

function baseUrlFor(p: ResolvedModel["provider"]): string {
  if (p.base_url) return p.base_url;
  if (p.slug === "lovable-gemini") return "https://ai.gateway.lovable.dev/v1";
  if (p.slug === "openai") return "https://api.openai.com/v1";
  return "";
}

/**
 * Mirrors resolveModelForTask on the client:
 * user preference → task default → (tier_<x> when a tier is given) → system_ai.
 */
async function resolveModel(
  admin: SupabaseClient,
  taskType: string,
  tier: string | null,
  userId: string | null,
): Promise<ResolvedModel | null> {
  const select = "model_id, ai_models ( id, name, model_id, cost_per_1k_input, cost_per_1k_output, is_enabled, ai_providers ( id, slug, base_url, auth_header_name, auth_header_prefix, is_enabled ) )";
  const shape = (row: any): ResolvedModel | null => {
    const m = row?.ai_models;
    if (!m || !m.ai_providers || m.is_enabled === false) return null;
    return {
      modelId: m.model_id,
      modelName: m.name,
      provider: m.ai_providers,
      costPer1kInput: m.cost_per_1k_input,
      costPer1kOutput: m.cost_per_1k_output,
    };
  };

  // Tier requests resolve through the tier defaults first.
  if (tier) {
    const { data } = await admin.from("ai_task_defaults").select(select).eq("task_type", `tier_${tier}`).maybeSingle();
    const r = shape(data);
    if (r) return r;
  }

  if (userId) {
    const { data } = await admin
      .from("user_model_preferences")
      .select(select)
      .eq("user_id", userId)
      .eq("task_type", taskType)
      .maybeSingle();
    const r = shape(data);
    if (r) return r;
  }

  const { data: def } = await admin.from("ai_task_defaults").select(select).eq("task_type", taskType).maybeSingle();
  const r = shape(def);
  if (r) return r;

  if (taskType !== "system_ai") {
    const { data: sys } = await admin.from("ai_task_defaults").select(select).eq("task_type", "system_ai").maybeSingle();
    return shape(sys);
  }
  return null;
}

/** Secret from ai_provider_secrets, else an env var for that provider. */
async function providerKey(admin: SupabaseClient, providerId: string, slug: string): Promise<string | null> {
  const { data } = await admin.from("ai_provider_secrets").select("api_key").eq("provider_id", providerId).maybeSingle();
  if (data?.api_key) return data.api_key;
  const envBySlug: Record<string, string> = {
    anthropic: "ANTHROPIC_API_KEY",
    "google-ai-studio": "GOOGLE_AI_API_KEY",
    openai: "OPENAI_API_KEY",
    "lovable-gemini": "LOVABLE_API_KEY",
  };
  const envName = envBySlug[slug];
  return envName ? Deno.env.get(envName) ?? null : null;
}

async function modelRate(admin: SupabaseClient, slug: string, modelId: string, resolved: ResolvedModel): Promise<ModelRate | null> {
  const { data } = await admin
    .from("model_rates")
    .select("input_per_1m, output_per_1m, cache_read_per_1m, cache_write_per_1m")
    .eq("provider_slug", slug)
    .eq("model_id", modelId)
    .eq("is_active", true)
    .maybeSingle();
  if (data) return data as ModelRate;
  // Fall back to the per-1k numbers on ai_models, if the admin filled them in.
  if (resolved.costPer1kInput != null || resolved.costPer1kOutput != null) {
    return {
      input_per_1m: (resolved.costPer1kInput ?? 0) * 1000,
      output_per_1m: (resolved.costPer1kOutput ?? 0) * 1000,
      cache_read_per_1m: null,
      cache_write_per_1m: null,
    };
  }
  return null;
}

async function creditEconomics(admin: SupabaseClient): Promise<CreditEconomics> {
  const { data } = await admin.from("platform_settings").select("setting_value").eq("setting_key", "credit_economics").maybeSingle();
  const v = (data?.setting_value ?? {}) as Partial<CreditEconomics>;
  return {
    retail_usd_per_credit: Number(v.retail_usd_per_credit) || DEFAULT_CREDIT_ECONOMICS.retail_usd_per_credit,
    cogs_multiplier: Number(v.cogs_multiplier) || DEFAULT_CREDIT_ECONOMICS.cogs_multiplier,
  };
}
